<?php if(is_singular('post')):while(have_posts()):the_post();?><article class="pp-article pp-container"><a href="<?php echo esc_url(prime_page_link('blog'));?>">← All articles</a><p class="pp-eyebrow"><?php echo esc_html(get_the_date('j F Y'));?></p><h1><?php the_title();?></h1><?php if(has_post_thumbnail())the_post_thumbnail('large',['class'=>'pp-article-photo']);else echo '<div class="pp-photo-placeholder">Article photograph pending</div>';?><?php $article=prime_article_body(apply_filters('the_content',get_the_content())); echo $article; ?><div class="pp-article-nav"><?php previous_post_link('%link','← %title');?><?php next_post_link('%link','%title →');?></div></article><?php echo prime_related_posts(get_the_ID()); endwhile;echo do_shortcode(do_blocks(prime_cta()));
else: $key=prime_page_key();$page=prime_page_object($key);$content=$page?$page->post_content:'';if(str_contains($content,'prime-approved-content'))echo apply_filters('the_content',$content);else echo do_shortcode(do_blocks(prime_pattern($key)));endif; ?>
